Now index.js. Use fsevents API. Need to handle non-darwin gracefully.

```js
'use strict';

const path = require('node:path');

let fsevents;
try {
  fsevents = require('fsevents');
} catch {
  fsevents = null;
}

function watch(target, onEvent) {
  if (!fsevents) {
    throw new Error(
      'fsevents is only available on macOS. Install it with "npm install fsevents" on a Darwin host.'
    );
  }
  const dir = path.resolve(target);
  const stop = fsevents.watch(dir, (changedPath, flags) => {
    const info = fsevents.getInfo(changedPath, flags);
    onEvent(info);
  });
  return () => fsevents.stop(stop);
}

if (require.main === module) {
  const target = process.argv[2] || process.cwd();
  console.log(`Watching ${target} (Ctrl+C to stop)`);
  const stop = watch(target, (info) => {
    const changes = Object.keys(info.changes).filter((k) => info.changes[k]);
    console.log(
      `${new Date().toISOString()} ${info.event.padEnd(8)} ${info.type.padEnd(9)} ${info.path}${
        changes.length ? ` [${changes.join(', ')}]` : ''
      }`
    );
  });
  process.on('SIGINT', () => {
    stop();
    process.exit(0);
  });
}

module.exports = { watch };
```

